def reconcile(legacy, platform):
    L = dict(legacy)
    P = dict(platform)
    lk, pk = set(L), set(P)

    return {
        "missing": sorted(lk - pk),
        "extra": sorted(pk - lk),
        "mismatched": sorted(
            [k, L[k], P[k]] for k in (lk & pk) if L[k] != P[k]
        ),
    }

